# PostgreSQL Connection Pool in Node.js

## Installation

```bash
npm install pg
npm install @types/pg  # If using TypeScript
```

## Basic Pool Setup

```javascript
// db/pool.js
const { Pool } = require('pg');

const pool = new Pool({
  // Connection settings
  host: process.env.DB_HOST || 'localhost',
  port: parseInt(process.env.DB_PORT || '5432'),
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Pool sizing
  min: 2,                  // Minimum connections kept alive
  max: 10,                 // Maximum connections in pool

  // Timeout settings (all in milliseconds)
  connectionTimeoutMillis: 5000,   // Wait for available connection
  idleTimeoutMillis: 30000,        // Remove idle connections after
  query_timeout: 10000,            // Max time for a query to complete
  statement_timeout: 10000,        // Max time before statement cancelled (server-side)

  // SSL (for production)
  ssl: process.env.NODE_ENV === 'production' 
    ? { rejectUnauthorized: true, ca: process.env.DB_SSL_CERT }
    : false,
});

// Handle pool-level errors (prevents process crash)
pool.on('error', (err, client) => {
  console.error('Unexpected error on idle client:', err);
});

pool.on('connect', (client) => {
  console.log('New client connected to pool');
});

pool.on('remove', (client) => {
  console.log('Client removed from pool');
});

module.exports = pool;
```

## Query Helper with Error Handling

```javascript
// db/query.js
const pool = require('./pool');

class DatabaseError extends Error {
  constructor(message, code, query) {
    super(message);
    this.name = 'DatabaseError';
    this.code = code;
    this.query = query;
  }
}

// Simple query - auto-releases connection
async function query(text, params) {
  const start = Date.now();

  try {
    const result = await pool.query(text, params);
    const duration = Date.now() - start;

    console.log('Query executed', {
      query: text,
      duration: `${duration}ms`,
      rows: result.rowCount,
    });

    return result;
  } catch (err) {
    handleQueryError(err, text);
  }
}

// Manual client for transactions
async function getClient() {
  const client = await pool.connect();

  // Wrap release to add safety timeout
  const originalRelease = client.release.bind(client);
  const releaseTimeout = setTimeout(() => {
    console.error('Client checked out for too long - force releasing');
    originalRelease();
  }, 30000);

  client.release = () => {
    clearTimeout(releaseTimeout);
    originalRelease();
  };

  return client;
}

function handleQueryError(err, queryText) {
  const errorMap = {
    '23505': 'Duplicate entry - record already exists',
    '23503': 'Foreign key violation - referenced record not found',
    '23502': 'Not null violation - required field missing',
    '42P01': 'Table does not exist',
    '28P01': 'Invalid database credentials',
    '3D000': 'Database does not exist',
    'ECONNREFUSED': 'Database connection refused',
    '57014': 'Query cancelled due to timeout',
  };

  const userMessage = errorMap[err.code] || 'Database operation failed';
  console.error('Database error:', { code: err.code, message: err.message, query: queryText });

  throw new DatabaseError(userMessage, err.code, queryText);
}

module.exports = { query, getClient, DatabaseError };
```

## Transaction Helper

```javascript
// db/transaction.js
const { getClient } = require('./query');

async function withTransaction(callback) {
  const client = await getClient();

  try {
    await client.query('BEGIN');
    const result = await callback(client);
    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK');
    throw err;  // Re-throw so caller can handle
  } finally {
    client.release();  // Always release, even if rollback fails
  }
}

module.exports = { withTransaction };
```

## Usage Examples

```javascript
// examples/usage.js
const { query, DatabaseError } = require('./db/query');
const { withTransaction } = require('./db/transaction');

// --- Simple query ---
async function getUser(id) {
  try {
    const { rows } = await query(
      'SELECT id, name, email FROM users WHERE id = $1',
      [id]
    );
    return rows[0] || null;
  } catch (err) {
    if (err instanceof DatabaseError) {
      // Handle specific DB errors
      console.error('Failed to fetch user:', err.message);
    }
    throw err;
  }
}

// --- Transaction example ---
async function transferFunds(fromId, toId, amount) {
  return withTransaction(async (client) => {
    const { rows: [sender] } = await client.query(
      'SELECT balance FROM accounts WHERE id = $1 FOR UPDATE',
      [fromId]
    );

    if (sender.balance < amount) {
      throw new Error('Insufficient funds');  // Triggers rollback
    }

    await client.query(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId]
    );

    await client.query(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );

    await client.query(
      'INSERT INTO transfers (from_id, to_id, amount) VALUES ($1, $2, $3)',
      [fromId, toId, amount]
    );

    return { success: true };
  });
}
```

## Health Check & Graceful Shutdown

```javascript
// db/health.js
const pool = require('./pool');

async function checkHealth() {
  const client = await pool.connect();
  try {
    await client.query('SELECT 1');
    return {
      status: 'healthy',
      totalConnections: pool.totalCount,
      idleConnections: pool.idleCount,
      waitingClients: pool.waitingCount,
    };
  } finally {
    client.release();
  }
}

// Graceful shutdown
async function shutdown() {
  console.log('Closing database pool...');
  await pool.end();
  console.log('Pool closed');
}

process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

module.exports = { checkHealth };
```

## Key Concepts Summary

| Setting | Recommended Value | Purpose |
|---|---|---|
| `min` | 2 | Prevents cold starts |
| `max` | 10-20 | Limit DB connections |
| `connectionTimeoutMillis` | 5000 | Fail fast if pool exhausted |
| `idleTimeoutMillis` | 30000 | Clean up unused connections |
| `statement_timeout` | Query-dependent | Prevent runaway queries |

**Critical rules:**
- Always use `$1, $2` parameterized queries — never string interpolation
- Always release clients in a `finally` block
- Always handle the pool-level `error` event or your process will crash
- Use `FOR UPDATE` in transactions to prevent race conditions
